        line = self.stream.readline()
        if not line:
            raise ConnectionError('redis disconnected')
        tag, value = line[:1], line[1:-2]
        if tag == b'+':
            return value.decode()
        if tag == b'-':
            raise RedisError(value.decode())
        if tag == b':':
