        items=rows[offset:offset+state['page_size']]
        next_offset=offset+len(items) if offset+len(items)<len(rows) else None
        expected={'revision':revision,'start':offset,'items':items,'next_offset':next_offset,'previous_sha256':chain}
        if page!=expected:raise ValueError('page changed or cursor skipped')
        chain=digest(page);descriptors.append({'file':'pages/'+path.name,'sha256':chain})
        offset+=len(items)
        if next_offset is None and index!=state['page_count']-1:raise ValueError('pages after terminal cursor')
    complete=state['page_count']>0 and offset==len(rows)
    if state['offset']!=offset or state['chain_sha256']!=chain or state['complete']is not complete:
        raise ValueError('checkpoint progress mismatch')
    return descriptors


def csv_bytes(rows):
    stream=io.StringIO(newline='');writer=csv.writer(stream,lineterminator='\n')
    writer.writerow(['member','score'])
    writer.writerows((r['member'],r['score'])for r in rows)
    return stream.getvalue().encode()


def final_manifest(directory,state,rows,revision):
    descriptors=validate_pages(directory,state,rows,revision)
    if not state['complete']:raise ValueError('export incomplete')
    return {'schema':1,'revision':revision,'count':len(rows),'native_sha256':digest(rows),
            'pages':descriptors,'chain_sha256':state['chain_sha256'],
            'csv_sha256':hashlib.sha256(csv_bytes(rows)).hexdigest()}


def main(argv=None):
    parser=argparse.ArgumentParser()
    parser.add_argument('phase',choices=['freeze','correct','export','promote'])
    parser.add_argument('--port',required=True,type=int);parser.add_argument('--prefix',required=True)
    parser.add_argument('--generation',required=True);parser.add_argument('--root',required=True)
    parser.add_argument('--live');parser.add_argument('--from-generation')
    parser.add_argument('--member');parser.add_argument('--score',type=int)
    parser.add_argument('--page-size',type=int,default=2);parser.add_argument('--budget',type=int,default=1)
    args=parser.parse_args(argv);valid_generation(args.generation)
    if not re.fullmatch(r'of:[a-f0-9]{16,48}:',args.prefix):raise ValueError('dedicated prefix')
    if not 1<=args.page_size<=100 or not 1<=args.budget<=10000:raise ValueError('export budget')
    directory=prepare_directory(args.root,args.generation)
    client=Client('127.0.0.1',args.port);c=client.command
    head=args.prefix+'head';snapshot=args.prefix+args.generation+':snapshot'
    revkey=args.prefix+args.generation+':revision';marker=args.prefix+args.generation+':published'
    try:
        if args.phase in ('freeze','correct'):
            if (directory/'plan.json').exists():
                plan=read_json(directory/'plan.json')
                if plan['operation']!=args.phase:raise ValueError('operation changed')
                if args.phase=='freeze' and plan['source']!=args.live:raise ValueError('source changed')
                if args.phase=='correct' and (plan['from_generation']!=args.from_generation or
                        plan['correction']!={'member':args.member,'score':args.score}):
                    raise ValueError('correction changed')
            else:
                base=c('GET',head)
                if args.phase=='freeze':
                    if not args.live or args.live.startswith(args.prefix):raise ValueError('external live required')
                    source=args.live;source_revision=None
                else:
                    valid_generation(args.from_generation)
                    if args.from_generation==args.generation or not args.member or type(args.score)is not int or abs(args.score)>2**53-1:
                        raise ValueError('correction identity')
                    source=args.prefix+args.from_generation+':snapshot'
                    source_revision=c('GET',args.prefix+args.from_generation+':revision')
                    if source_revision is None:raise ValueError('source revision missing')
                c('WATCH',source,head)
                rows=ranked(c,source)
                c('MULTI');c('PING')
                if c('EXEC')is None:raise ValueError('concurrent source change')
                plan={'schema':1,'generation':args.generation,'prefix':args.prefix,'operation':args.phase,
                      'base':base,'source':source,'source_revision':source_revision,'source_rows':rows}
                if args.phase=='correct':plan.update(from_generation=args.from_generation,correction={'member':args.member,'score':args.score})
                write_new(directory/'plan.json',plan)
            revision=args.generation+':'+digest(plan)
            rows=expectation(plan)
            if c('EXISTS',revkey)==0:
                if args.phase=='freeze':task.freeze(c,plan['source'],snapshot,revkey,revision)
                else:
                    oldrev=args.prefix+plan['from_generation']+':revision'
                    if c('GET',oldrev)!=plan['source_revision'] or ranked(c,plan['source'])!=plan['source_rows']:
                        raise ValueError('correction source drift')
                    task.corrected(c,plan['source'],oldrev,snapshot,revkey,revision,args.member,args.score)
            if c('GET',revkey)!=revision or ranked(c,snapshot)!=rows:raise ValueError('frozen snapshot differs')
            native={'schema':1,'revision':revision,'count':len(rows),'native_sha256':digest(rows),
                    'operation':plan['operation'],'source_sha256':digest(plan['source_rows'])}
            write_new(directory/'native.json',native)
            write_new(directory/'changes.json',changes_for(plan,rows))
            print(json.dumps({'phase':args.phase,'revision':revision,'count':len(rows)}));return
        plan=read_json(directory/'plan.json')
        if plan['generation']!=args.generation or plan['prefix']!=args.prefix:raise ValueError('plan identity')
        revision=args.generation+':'+digest(plan);rows=expectation(plan)
        native={'schema':1,'revision':revision,'count':len(rows),'native_sha256':digest(rows),
                'operation':plan['operation'],'source_sha256':digest(plan['source_rows'])}
        if (read_json(directory/'native.json')!=native or read_json(directory/'changes.json')!=changes_for(plan,rows) or c('GET',revkey)!=revision or ranked(c,snapshot)!=rows):
            raise ValueError('native source or receipt differs')
        state=read_json(directory/'checkpoint.json')if(directory/'checkpoint.json').exists()else{
            'revision':revision,'native_sha256':digest(rows),'page_size':args.page_size,'page_count':0,
            'offset':0,'chain_sha256':'0'*64,'complete':False}
        validate_pages(directory,state,rows,revision)
        if args.phase=='export':
            if state['page_size']!=args.page_size:raise ValueError('page size changed during resume')
            already_complete=state['complete']
            for _ in range(args.budget):
                if state['complete']:break
                offset=state['offset'];result=task.page(c,snapshot,revkey,revision,offset,state['page_size'])
                items=rows[offset:offset+state['page_size']]
                next_offset=offset+len(items)if offset+len(items)<len(rows)else None
                if result!={'revision':revision,'items':items,'next_offset':next_offset}:raise ValueError('native page differs')
                page={'revision':revision,'start':offset,'items':items,'next_offset':next_offset,'previous_sha256':state['chain_sha256']}
                write_new(pages_directory(directory)/('%06d.json'%state['page_count']),page)
                state.update(offset=offset+len(items),page_count=state['page_count']+1,
                             chain_sha256=digest(page),complete=next_offset is None)
                checkpoint(directory/'checkpoint.json',state)
            if state['complete'] and not already_complete:
                manifest=final_manifest(directory,state,rows,revision)
                publish_bytes(directory/'rows.csv',csv_bytes(rows));write_new(directory/'manifest.json',manifest)
            print(json.dumps({'phase':'export','complete':state['complete'],'offset':state['offset']}));return
        manifest=final_manifest(directory,state,rows,revision)
        if read_json(directory/'manifest.json')!=manifest or (directory/'rows.csv').read_bytes()!=csv_bytes(rows):
            raise ValueError('materialization differs')
        receipt={'schema':1,'generation':args.generation,'revision':revision,'manifest_sha256':digest(manifest),'base':plan['base']}
        c('WATCH',head,revkey,snapshot,marker)
        if c('GET',revkey)!=revision or ranked(c,snapshot)!=rows:raise ValueError('native drift')
        previous=c('GET',marker)
        if previous is not None:
            if json.loads(previous)!=receipt:raise ValueError('receipt differs')
        else:
            if c('GET',head)!=plan['base']:raise ValueError('stale head')
            c('MULTI');c('SET',head,args.generation);c('SET',marker,canonical(receipt))
            if c('EXEC')is None:raise ValueError('concurrent publication')
        write_new(directory/'published.json',receipt)
        print(json.dumps({'phase':'promote','committed':True,**receipt}))
    finally:client.close()


if __name__=='__main__':
    try:main()
    except (ValueError,KeyError,TypeError,OSError,RedisError)as error:
        print(str(error),file=sys.stderr);raise SystemExit(2)
